use crate::{Sim,SimEvent};
use super::{*,act};
#[derive(Clone,Debug,Serialize,Deserialize)]pub struct Row{pub name:String,pub detail:String,pub value:Option<[f32;3]>}
impl Row{fn text(s:impl Into<String>)->Self{Self{name:s.into(),detail:String::new(),value:None}}fn toggle(s:&str,b:bool)->Self{Self{name:s.into(),detail:if b{"On"}else{"Off"}.into(),value:None}}fn slider(s:&str,v:f32,a:f32,z:f32)->Self{Self{name:s.into(),detail:format!("{v:.2}"),value:Some([v,a,z])}}}
impl Merc{
 pub fn rows(&self)->Vec<Row>{let labels=|l:&[&str]|l.iter().map(|s|Row::text(self.s(s))).collect::<Vec<_>>();let page=self.page*6;match self.screen.as_str(){
 "title"=>labels(&["continue","new","multiplayer","settings","about"]),"difficulty"=>labels(&["Easy","Normal","Hard"]),"dossier"=>(0..4).map(|i|{let key=format!("dossier_{i}");let text=self.s(&key);let (name,detail)=text.split_once('|').unwrap();Row{name:name.into(),detail:detail.into(),value:None}}).collect(),
 "pause"=>labels(&["resume","settings","controls","dev","quit"]),"quit"=>labels(&["Return to title","resume"]),"death"=>labels(&["Reload autosave","Return to title"]),"ending"=>labels(&["end_return","about"]),"ending_choice"=>labels(&["burn_choice","read_choice","chair_choice"]),
 "contract"=>labels(&[if self.contract_active{"resume"}else{"accept"},"decline"]),"town"=>labels(&["contract","shop_title","companion","tape","bus","clinic"]),"safehouse"=>labels(&["sleep","inventory","Resupply","Manual saves","tape"]),"sleep"=>labels(&["Dawn · 06:00","Noon · 12:00","Dusk · 18:00","Midnight · 00:00"]),
 "saves"=>(0..6).map(|i|Row::text(format!("{} {}",if i<3{"Save slot"}else{"Load slot"},i%3+1))).collect(),
 "shop"=>{let names:Vec<_>=self.data.weapons.iter().map(|w|w.name.clone()).chain(["Reliability","Accuracy","Ammo pouch","Syrette bandolier","Vehicle kit","Camo suit","Quinine · 3 pills","Quinine reserve"].iter().map(|s|s.to_string())).collect();names.iter().enumerate().skip(page).take(6).map(|(i,n)|Row{name:n.clone(),detail:if i<14&&self.owned.contains(&i){"Licensed · fresh at every locker".into()}else{format!("{} diamonds",if i<14{[5,5,4,5,8,10,8,8,12,10,12,12,14,12][i]}else{[6,6,6,8,10,5,7,7][i-14]})},value:None}).collect()},
 "locker"=>self.owned.iter().skip(page).take(6).map(|i|Row{name:self.data.weapons[*i].name.clone(),detail:"Fresh crate · New".into(),value:None}).collect(),
 "bus"=>["town","junction","bus_mission"].iter().map(|id|Row::text(self.data.place(id).name.clone())).collect(),"clinic"=>labels(&["Medicine errand · 3 diamonds","Refill quinine · 5 diamonds","back"]),
 "companion"=>labels(&["patch","overdose"]),"evacuate"=>labels(&["Save Papa Lazare","Save Mr. Desai"]),"tapes"=>self.tapes.iter().skip(page).take(6).map(|i|Row::text(self.data.tapes[*i].name.clone())).collect(),"recruit"=>self.companions.iter().map(|c|Row{name:self.s(&format!("dossier_{}",c.merc)).split('|').next().unwrap_or("").into(),detail:if !c.alive{"Empty stool"}else if c.recruited{"With you"}else{"Available"}.into(),value:None}).collect(),
 "settings"|"session_settings"=>{let s=&self.settings;match self.page%4{0=>vec![Row::slider("Master",s.master,0.,1.),Row::slider("Music",s.music,0.,1.),Row::slider("Sound effects",s.sfx,0.,1.),Row::slider("Voices",s.voices,0.,1.)],1=>vec![Row{name:"Prompt symbols".into(),detail:if s.xbox{"Xbox"}else{"PlayStation"}.into(),value:None},Row::toggle("Invert Y",s.invert),Row::slider("Stick sensitivity",s.stick,40.,240.),Row::slider("Mouse sensitivity",s.mouse,0.02,0.4),Row::toggle("Aim assist",s.aim_assist),Row::toggle("Toggle crouch",s.toggle_crouch)],2=>vec![Row::toggle("Fullscreen",s.fullscreen),Row::slider("Field of view",s.fov,55.,100.),Row::slider("Brightness",s.brightness,0.5,1.5),Row::slider("Head bob",s.bob,0.,1.)],_=>vec![Row::slider("Subtitle size",s.subtitles,0.8,1.4),Row::slider("Reduce camera motion",1.-s.motion,0.,1.),Row::toggle("Assist markers",s.markers),Row::toggle("Standard HUD",s.standard)]}},
 "controls"|"about"=>Vec::new(),"multiplayer"=>labels(&["solo","invite"]),"local_lobby"=>labels(&["create","join","start"]),"invite"=>labels(&["Create offer","Create answer","Connect answer","Copy code","back"]),
 "dev"=>labels(&["dev_cheats","dev_teleport","dev_story","dev_give","dev_world","dev_balance"]),
 "dev_cheats"=>{let c=&self.cheats;[Row::toggle("God mode",c.god),Row::toggle("Infinite ammo",c.ammo),Row::toggle("No jams",c.jams),Row::toggle("No fever",c.fever),Row::toggle("Noclip",c.noclip),Row::toggle("Invisible to AI",c.invisible),Row::toggle("AI state",c.ai),Row::toggle("Fire grid",c.fire),Row::toggle("Navigation",c.nav),Row::toggle("FPS and tick stats",c.stats)].into_iter().skip(page).take(6).collect()},
 "dev_teleport"=>self.data.world.place.iter().skip(page).take(6).map(|p|Row::text(p.name.clone())).collect(),"dev_story"=>self.data.contracts.iter().skip(page).take(6).map(|p|Row::text(p.name.clone())).collect(),
 "dev_give"=>["Rifle squad","Flame trooper","Technical","River boat","Fresh weapon","Rusted weapon","10 diamonds","5 pills","5 syrettes","Kill nearby"].iter().skip(page).take(6).map(|s|Row::text(*s)).collect(),
 "dev_world"=>[Row::slider("Time of day",self.hour,0.,24.),Row::slider("Wind speed",self.wind_speed,0.,12.),Row::slider("Wind direction",self.wind.y.atan2(self.wind.x),-3.14,3.14),Row::text("Cycle weather"),Row::text("Ignite at sight"),Row::text("Extinguish all"),Row::text("Regrow the country"),Row::text(self.s("reset"))].into_iter().skip(page).take(6).collect(),
 "dev_balance"=>{let mut tuning=self.tuning.clone();let mut r=crate::params::list(&mut tuning).into_iter().map(|p|{if let crate::params::ParamKind::Float{min,max}=p.kind{Row::slider(&p.help,p.value.as_f64().unwrap_or(0.) as f32,min,max)}else{Row::text(p.help)}}).collect::<Vec<_>>();r.push(Row::text(self.s("reset")));r.into_iter().skip(page).take(6).collect()},_=>Vec::new()}}
 pub fn page_count(&self)->usize{match self.screen.as_str(){"shop"=>4,"locker"=>self.owned.len().div_ceil(6).max(1),"tapes"=>self.tapes.len().div_ceil(6).max(1),"settings"|"session_settings"=>4,"about"=>self.data.about.len(),"controls"=>3,"dev_cheats"|"dev_give"|"dev_story"=>2,"dev_teleport"=>4,"dev_world"=>2,"dev_balance"=>4,_=>1}}
 pub fn menu_input(&mut self,sim:&mut Sim,a:u32,events:&mut Vec<SimEvent>){let n=self.rows().len();match a{act::UP=>{if n>0{self.focus=(self.focus+n-1)%n;}self.sound(0);},act::DOWN=>{if n>0{self.focus=(self.focus+1)%n;}self.sound(0);},act::PREV|act::NEXT=>{let pages=self.page_count();self.page=if a==act::NEXT{(self.page+1)%pages}else{(self.page+pages-1)%pages};self.focus=0;self.sound(0);},act::LEFT|act::RIGHT=>{let sign=if a==act::LEFT{-1.}else{1.};if self.screen=="settings"||self.screen=="session_settings"{self.adjust_setting(sign);}else if self.screen=="dev_balance"{let i=self.page*6+self.focus;let mut ps=crate::params::list(&mut sim.config.merc);if let Some(p)=ps.get_mut(i){if let crate::params::ParamKind::Float{min,max}=p.kind{let val=(p.value.as_f64().unwrap() as f32+sign*(max-min)/40.).clamp(min,max);let _=crate::params::set(&mut sim.config.merc,&p.path,crate::params::ParamValue::Float(val as f64));self.tuning=sim.config.merc.clone();}}}else if self.screen=="dev_world"{self.adjust_world(sign);}else{self.menu_input(sim,if a==act::LEFT{act::PREV}else{act::NEXT},events);}},act::CONFIRM=>self.select(sim,events),act::BACK=>{let s=match self.screen.as_str(){"settings"|"controls"|"about"=>self.parent.clone(),"session_settings"=>"playing".into(),"dev_cheats"|"dev_teleport"|"dev_story"|"dev_give"|"dev_world"|"dev_balance"=>"dev".into(),"dev"=>"pause".into(),"difficulty"|"dossier"|"multiplayer"=>"title".into(),"shop"|"recruit"|"tapes"|"clinic"|"bus"=>"playing".into(),_=>"playing".into()};self.open(&s);},_=>{}}}
 pub fn select(&mut self,sim:&mut Sim,events:&mut Vec<SimEvent>){let i=self.focus;let page=self.page;let screen=self.screen.clone();self.sound(0);match screen.as_str(){
 "title"=>match i{0=>{self.load_slot=0;},1=>self.open("difficulty"),2=>self.open("multiplayer"),3=>{self.parent="title".into();self.open("settings");},4=>{self.parent="title".into();self.open("about");},_=>{}},
 "difficulty"=>{self.difficulty=i as u8;sim.config.merc=Tuning::default();match i{0=>{sim.config.merc.enemy_damage=0.65;sim.config.merc.enemy_accuracy=0.18;sim.config.merc.wear=0.7;sim.config.merc.fever_interval=1200.;},2=>{sim.config.merc.enemy_damage=1.4;sim.config.merc.enemy_accuracy=0.4;sim.config.merc.wear=1.4;sim.config.merc.fever_interval=720.;},_=>{}}self.open("dossier");},"dossier"=>{let settings=self.settings.clone();let difficulty=self.difficulty;for n in &self.soldiers{if let Some(id)=n.entity{sim.despawn(id);}}*self=Merc::new(self.seed);self.settings=settings;self.difficulty=difficulty;self.start(i);self.sync_player(sim);},
 "pause"=>match i{0=>self.open("playing"),1=>{self.parent="pause".into();self.open("settings");},2=>{self.parent="pause".into();self.open("controls");},3=>self.open("dev"),4=>self.open("quit"),_=>{}},"quit"=>{self.open(if i==0{"title"}else{"playing"});},
 "death"=>{if i==0{self.load_slot=0;}else{self.open("title");}},"ending"=>{self.parent="ending".into();self.open(if i==0{"title"}else{"about"});},"ending_choice"=>self.choose_ending((i+1) as u8),
 "settings"|"session_settings"=>self.adjust_setting(1.),"contract"=>{if i==0&&!self.contract_active{self.accept_contract();}else{self.open("playing");}},
 "town"=>self.open(["contract","shop","recruit","tapes","bus","clinic"][i.min(5)]),
 "safehouse"=>match i{0=>self.open("sleep"),1=>self.open("locker"),2=>{for gun in &mut self.guns{gun.reserve=self.data.weapons[gun.def].reserve*if self.upgrades.contains(&0){2}else{1};}self.syrettes=if self.upgrades.contains(&1){5}else{3};self.molotov=4;self.grenades=4;self.note("Crates open. The bill arrives later.");},3=>self.open("saves"),4=>self.open("tapes"),_=>{}},
 "sleep"=>{self.hour=[6.,12.,18.,0.][i%4];self.world_hours+=8.;self.health=100.;self.stamina=12.;self.fever_timer=self.tuning.fever_interval;self.wind=glam::Vec2::from_angle(self.world_hours*0.3);self.wind_speed=5.+self.hour.sin().abs()*5.;for c in &mut self.companions{c.rescue=false;}self.flag("sleep_used");self.save_serial+=1;self.open("playing");},
 "saves"=>{if i<3{self.save_slot=i as i32+1;self.save_serial+=1;self.note(format!("Saved in slot {}.",i+1));}else{self.load_slot=(i-2) as i32;}},"shop"=>self.buy(page*6+i),"locker"=>{if let Some(w)=self.owned.iter().nth(page*6+i).copied(){let slot=self.data.weapons[w].slot;self.guns[slot]=Gun::new(w,&self.data.weapons[w],100.);self.active=slot;self.flag("locker_used");self.note("Fresh steel. Enjoy the interval.");}},
 "bus"=>{if self.diamonds>=1{self.diamonds-=1;let p=self.data.place(["town","junction","bus_mission"][i%3]).pos();self.pos=p+glam::Vec3::new(0.,0.,25.);self.pos.y=terrain::height(&self.data,self.pos.x,self.pos.z);self.riding=None;self.hour=(self.hour+2.).rem_euclid(24.);self.world_hours+=2.;self.flag("bus_taken");self.flag("diamonds_spent");self.sync_player(sim);self.open("playing");}else{self.note(self.s("no_money").to_string());}},
 "clinic"=>{if i==0{if self.diamonds>=3{self.diamonds-=3;self.pills+=3;self.infamy+=1;self.note("Medicine delivered to the annex. Quinine received.");}}else if i==1&&self.diamonds>=5{self.diamonds-=5;self.pills+=3;}else if i==2{self.open("playing");}},
 "recruit"=>{if let Some(c)=self.companions.get_mut(i){if c.alive{c.recruited=true;c.trust+=1;self.say("Companion",self.s("recruit").to_string());}}},"tapes"=>{if let Some(t)=self.tapes.iter().nth(page*6+i).copied(){self.playing_tape=Some(t);self.tape_line=0;self.tape_timer=0.;self.flag("tape_played");self.open("playing");}},
 "companion"=>{self.open("playing");self.command(sim,if i==0{act::PATCH}else{act::OVERDOSE},events);},"evacuate"=>{self.saved_person=i as u8+1;self.goal_flag=true;self.open("playing");self.say(if i==0{"Papa Lazare"}else{"Mr. Desai"},"I will remember this. That is not a promise of repayment.");},
 "multiplayer"=>self.open(if i==0{"local_lobby"}else{"invite"}),"local_lobby"|"invite"=>{self.net_ui=i as i32+if screen=="invite"{10}else{1};},
 "dev"=>self.open(["dev_cheats","dev_teleport","dev_story","dev_give","dev_world","dev_balance"][i.min(5)]),
 "dev_cheats"=>{let c=&mut self.cheats;let v=match page*6+i{0=>&mut c.god,1=>&mut c.ammo,2=>&mut c.jams,3=>&mut c.fever,4=>&mut c.noclip,5=>&mut c.invisible,6=>&mut c.ai,7=>&mut c.fire,8=>&mut c.nav,_=>&mut c.stats};*v=!*v;},
 "dev_teleport"=>self.command(sim,act::TELEPORT+(page*6+i) as u32,events),"dev_story"=>self.command(sim,act::STORY+(page*6+i) as u32,events),
 "dev_give"=>match page*6+i{0=>{for r in 0..5{self.spawn_enemy(sim,self.pos+glam::Vec3::new(12.+r as f32*3.,0.,-20.),r);}},1=>self.spawn_enemy(sim,self.pos+glam::Vec3::new(10.,0.,-15.),4),2|3=>{let mut v=self.vehicles[0].clone();v.pos=self.pos+glam::Vec3::new(6.,0.,0.);v.kind=if i==3{3}else{0};v.hp=100.;v.exploded=false;self.vehicles.push(v);},4=>self.guns[self.active].condition=100.,5=>self.guns[self.active].condition=5.,6=>self.diamonds+=10,7=>self.pills+=5,8=>self.syrettes+=5,_=>{let ids:Vec<_>=self.soldiers.iter().enumerate().filter(|(_,n)|n.hp>0.&&data::distance(n.pos,self.pos)<100.).map(|(i,_)|i).collect();for i in ids{self.hit_soldier(sim,i,1000.,events);}}},
 "dev_world"=>match page*6+i{0..=2=>self.adjust_world(1.),3=>{self.weather=(self.weather+1)%3;self.weather_time=90.;},4=>{self.fire.ignite(&self.data,data::flat(self.pos+self.forward()*12.),5.);},5=>{for c in self.fire.cells.values_mut(){c.state=2;c.time=0.;}},6=>self.fire=fire::Fire::default(),_=>{sim.config.merc=Tuning::default();self.tuning=Tuning::default();}},
 "dev_balance"=>{if page*6+i>=23{sim.config.merc=Tuning::default();self.tuning=Tuning::default();}else{self.menu_input(sim,act::RIGHT,events);}},_=>{}}
 }
 pub fn adjust_setting(&mut self,sign:f32){let f=self.focus;let s=&mut self.settings;match self.page%4{0=>{let v=match f{0=>&mut s.master,1=>&mut s.music,2=>&mut s.sfx,_=>&mut s.voices};*v=(*v+sign*0.05).clamp(0.,1.);},1=>match f{0=>s.xbox=!s.xbox,1=>s.invert=!s.invert,2=>s.stick=(s.stick+sign*10.).clamp(40.,240.),3=>s.mouse=(s.mouse+sign*0.01).clamp(0.02,0.4),4=>s.aim_assist=!s.aim_assist,_=>s.toggle_crouch=!s.toggle_crouch},2=>match f{0=>s.fullscreen=!s.fullscreen,1=>s.fov=(s.fov+sign*5.).clamp(55.,100.),2=>s.brightness=(s.brightness+sign*0.05).clamp(0.5,1.5),_=>s.bob=(s.bob+sign*0.1).clamp(0.,1.)},_=>match f{0=>s.subtitles=(s.subtitles+sign*0.1).clamp(0.8,1.4),1=>s.motion=(s.motion-sign*0.1).clamp(0.,1.),2=>s.markers=!s.markers,_=>s.standard=!s.standard}}}
 fn adjust_world(&mut self,sign:f32){match self.page*6+self.focus{0=>self.hour=(self.hour+sign).rem_euclid(24.),1=>self.wind_speed=(self.wind_speed+sign).clamp(0.,12.),2=>self.wind=glam::Vec2::from_angle(self.wind.y.atan2(self.wind.x)+sign*0.2),_=>{}}}
}
